import sys, os, csv, json, gzip, io
from datetime import datetime, timedelta, timezone, date
from zoneinfo import ZoneInfo
from fractions import Fraction
from decimal import Decimal

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    t = b.decode('utf-8')
    if t.startswith('\ufeff'):
        t = t[1:]
    return t


def lines_of(path):
    return [l for l in read_text(path).splitlines() if l.strip() != '']


def to_ts(naive, zone, dst=None):
    """naive local datetime -> epoch seconds. dst: True/False/None to pick fold."""
    a = naive.replace(tzinfo=zone, fold=0)
    b = naive.replace(tzinfo=zone, fold=1)
    if a.utcoffset() != b.utcoffset():
        if dst is None or dst:
            pick = a if a.dst() else b   # first occurrence is DST
            if dst is False:
                pick = b
            if dst is None or dst:
                pick = a if a.dst() else b
        else:
            pick = b if not b.dst() else a
        return int(pick.timestamp())
    return int(a.timestamp())


def std_offset(zone):
    for m in (1, 7, 4, 10):
        d = datetime(2026, m, 1, tzinfo=zone)
        if not d.dst():
            return d.utcoffset()
    return datetime(2026, 1, 1, tzinfo=zone).utcoffset()


def norm_dir(s):
    s = s.strip().upper()
    return 'IN' if s in ('IN', 'I', 'K', 'CLOCK_IN') else 'OUT'


def parse_abbr(path, zone):
    out = []
    hdr = None
    import csv as _c
    for row in _c.reader(lines_of(path)):
        cells = [c.strip() for c in row]
        if 'Badge' in cells and 'Punch' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        mo, d, y = map(int, g('Date').split('/'))
        t = g('Time').upper()
        ap = None
        if t.endswith('AM') or t.endswith('PM'):
            ap = t[-2:]
            t = t[:-2].strip()
        h, mi, s = map(int, t.split(':'))
        if ap:
            h = h % 12 + (12 if ap == 'PM' else 0)
        z = g('Zone').upper()
        dst = True if z.endswith('DT') else (False if z.endswith('ST') else None)
        ts = to_ts(datetime(y, mo, d, h, mi, s), zone, dst)
        out.append((g('Record'), g('Badge'), norm_dir(g('Punch')), ts))
    return out


def parse_epoch(path, zone):
    out = []
    schema = 1
    for l in lines_of(path):
        o = json.loads(l)
        if 'schema' in o and 'heartbeat' not in o and not ('id' in o or 'punch_id' in o):
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, d, ts = o['punch_id'], o['employee'], o['direction'], int(o['epoch_ms']) // 1000
        else:
            pid, emp, d = o['id'], o['emp'], o['dir']
            ts = int(o['ts_ms']) // 1000 if 'ts_ms' in o else int(o['ts'])
        out.append((str(pid), emp.strip(), norm_dir(d), ts))
    return out


def parse_offset(path, zone):
    out = []
    r = csv.DictReader(io.StringIO('\n'.join(lines_of(path))), delimiter=';')
    for row in r:
        dt = datetime.fromisoformat(row['timestamp'].strip())
        out.append((row['punch_id'], row['employee'].strip(), norm_dir(row['event']),
                    int(dt.timestamp())))
    return out


def parse_legacy(path, zone):
    out = []
    std = std_offset(zone)
    off = std
    for l in lines_of(path):
        t = l[0]
        if t == 'H':
            o = l[13:18].strip()
            if o:
                sign = -1 if o[0] == '-' else 1
                off = sign * timedelta(hours=int(o[1:3]), minutes=int(o[3:5]))
            else:
                off = std
        elif t == 'D':
            pid = l[1:9]
            badge = l[9:15].strip()
            d = l[15]
            dt = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            ts = int((dt - off - datetime(1970, 1, 1)).total_seconds())
            out.append((pid, 'E' + badge, norm_dir(d), ts))
    return out


def parse_de(path, zone):
    out = []
    r = csv.DictReader(io.StringIO('\n'.join(lines_of(path))), delimiter='\t')
    for row in r:
        row = {k.strip(): v.strip() for k, v in row.items()}
        d, mo, y = map(int, row['Datum'].split('.'))
        h, mi = map(int, row['Uhrzeit'].split(':')[:2])
        z = row['Zeitzone'].upper()
        dst = True if z == 'MESZ' else (False if z == 'MEZ' else None)
        ts = to_ts(datetime(y, mo, d, h, mi), zone, dst)
        out.append((row['Nr'], row['Ausweis'], norm_dir(row['Buchung']), ts))
    return out


def parse_localcsv(path, zone):
    out = []
    r = csv.DictReader(io.StringIO('\n'.join(lines_of(path))))
    for row in r:
        dt = datetime.strptime(row['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((row['punch_ref'].strip(), row['employee_id'].strip(),
                    norm_dir(row['direction']), to_ts(dt, zone, True)))
    return out


def parse_localjsonl(path, zone):
    out = []
    for l in lines_of(path):
        p = json.loads(l)['punch']
        dt = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'].strip(), norm_dir(p['type']), to_ts(dt, zone, True)))
    return out


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s)


def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_iso(period['corrections_cutoff'])
    if cutoff.tzinfo is None:
        cutoff = cutoff.replace(tzinfo=UTC)

    def rcsv(name):
        with open(os.path.join(inp, name), encoding='utf-8-sig', newline='') as f:
            return [{k.strip(): (v or '').strip() for k, v in r.items()} for r in csv.DictReader(f)]

    sites = {r['site']: (ZoneInfo(r['timezone']), r['format']) for r in rcsv('sites.csv')}
    emps = rcsv('employees.csv')
    emp_home = {e['employee_id']: e['home_site'] for e in emps}
    rates = {}
    for r in rcsv('rates.csv'):
        rates.setdefault(r['employee_id'], []).append((date.fromisoformat(r['effective_from']), Decimal(r['hourly_rate'])))
    for v in rates.values():
        v.sort()

    # 1 collect
    punches = {}   # (site,id) -> dict
    ever = set()
    for site, (zone, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for fn in sorted(os.listdir(d)):
            p = os.path.join(d, fn)
            if not os.path.isfile(p):
                continue
            for pid, emp, dr, ts in PARSERS[fmt](p, zone):
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = {'emp': emp, 'dir': dr, 'ts': ts}

    # 2 corrections
    corr = []
    cd = os.path.join(inp, 'corrections')
    if os.path.isdir(cd):
        for fn in os.listdir(cd):
            p = os.path.join(cd, fn)
            if os.path.isfile(p):
                r = csv.DictReader(io.StringIO('\n'.join(lines_of(p))))
                for row in r:
                    row = {k.strip(): (v or '').strip() for k, v in row.items()}
                    if row.get('correction_id') == 'correction_id':
                        continue
                    corr.append(row)
    corr = [(parse_iso(c['issued_at']), c) for c in corr]
    corr = [(t if t.tzinfo else t.replace(tzinfo=UTC), c) for t, c in corr]
    corr = [x for x in corr if x[0] <= cutoff]
    corr.sort(key=lambda x: (x[0], x[1]['correction_id']))
    applied = 0
    voided = set()
    for _, c in corr:
        k = (c['site'], c['punch_id'])
        a = c['action']
        if a == 'void':
            if k in punches:
                del punches[k]
                voided.add(k)
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k]['ts'] = int(parse_iso(c['time']).timestamp())
                applied += 1
        elif a == 'add':
            if k not in ever and c['site'] in sites:
                ever.add(k)
                punches[k] = {'emp': c['employee'], 'dir': norm_dir(c['type']),
                              'ts': int(parse_iso(c['time']).timestamp())}
                applied += 1
    byemp = {}
    for (site, pid), p in punches.items():
        if p['emp'] in emp_home:
            byemp.setdefault(p['emp'], []).append((p['ts'], 0 if p['dir'] == 'OUT' else 1, site, pid, p['dir']))

    res = {}
    exc = {'open_shifts': 0, 'orphan_outs': 0, 'duplicates_dropped': 0, 'corrections_applied': applied}
    for e in emps:
        res[e['employee_id']] = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross='0.00')

    def rnd(ts, zone):
        off = int(datetime.fromtimestamp(ts, zone).utcoffset().total_seconds())
        return ((ts + off + 180) // 360) * 360 - off

    for emp, lst in byemp.items():
        hz = sites[emp_home[emp]][0]
        wd = lambda ts: datetime.fromtimestamp(ts, hz).date()
        lst.sort()
        kept = []
        for ts, _, site, pid, dr in lst:
            if kept and kept[-1][1] == dr and ts - kept[-1][3] <= 300:
                # duplicate; workday from rounded instant
                r = rnd(ts, sites[site][0])
                if pstart <= wd(r) <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            r = rnd(ts, sites[site][0])
            kept.append((site, dr, r, ts))
        shifts = []
        cur = None
        def open_(p):
            if pstart <= wd(p[2]) <= pend:
                exc['open_shifts'] += 1
        for p in kept:
            if p[1] == 'IN':
                if cur:
                    open_(cur)
                cur = p
            else:
                if cur and p[2] - cur[2] <= 16 * 3600:
                    shifts.append((cur, p))
                else:
                    if cur:
                        open_(cur)
                    if pstart <= wd(p[2]) <= pend:
                        exc['orphan_outs'] += 1
                cur = None
        if cur:
            open_(cur)
        rows = []
        for i, o in shifts:
            w = wd(i[2])
            if not (pstart <= w <= pend):
                continue
            zone = sites[i[0]][0]
            worked = max(0, (o[2] - i[2]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = 0
            t = i[2]
            while t < o[2]:
                h = datetime.fromtimestamp(t, zone).hour
                if h >= 22 or h < 6:
                    night += 1
                t += 60
            night = min(night, paid)
            rows.append([i[2], w, paid, night, 0, 0])
        rows.sort(key=lambda r: r[0])
        daycum = {}
        for r in rows:
            before = daycum.get(r[1], 0)
            after = before + r[2]
            daycum[r[1]] = after
            r[4] = max(0, after - 480) - max(0, before - 480)
        weekcum = {}
        for r in rows:
            wk = r[1] - timedelta(days=r[1].weekday())
            nd = r[2] - r[4]
            before = weekcum.get(wk, 0)
            after = before + nd
            weekcum[wk] = after
            r[5] = max(0, after - 2400) - max(0, before - 2400)
        pay = Fraction(0)
        s = res[emp]
        for r in rows:
            ot = r[4] + r[5]
            reg = r[2] - ot
            rate = Decimal(0)
            for ef, rt in rates.get(emp, []):
                if ef <= r[1]:
                    rate = rt
            rate = Fraction(rate)
            pay += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * r[3] / 60
            s['shifts'] += 1
            s['paid_minutes'] += r[2]
            s['overtime_minutes'] += ot
            s['night_minutes'] += r[3]
        cents = int(pay * 100 + Fraction(1, 2) // 1) if False else (pay * 100 + Fraction(1, 2)).__floor__()
        s['gross'] = '%d.%02d' % divmod(cents, 100)

    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    g = 0
    for s in res.values():
        for k in tot:
            tot[k] += s[k]
        a, b = s['gross'].split('.')
        g += int(a) * 100 + int(b)
    tot['gross'] = '%d.%02d' % divmod(g, 100)
    with open(outp, 'w') as f:
        json.dump({'period': {'start': period['start'], 'end': period['end']},
                   'employees': res, 'exceptions': exc, 'totals': tot}, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
